// Direct imports avoid services barrel (saves pulling all 30+ service instances into main chunk)
import { LocalStorage } from 'quasar';
import UserApiService from 'src/services/user/userApiService';
import subscriptionUtil from 'src/utils/subscriptionUtil';
import { safeBoot } from 'src/utils/bootSafety';

const userApiService = new UserApiService();

export default safeBoot('SubscriptionAndConnectionChecker', () => {
  // Skip on /auth routes — no org context, nothing to check.
  if (
    typeof window !== 'undefined' &&
    window.location.pathname.startsWith('/auth')
  ) {
    return;
  }

  // A persisted org_id is NOT proof of a logged-in user, so it cannot be the
  // only gate here (DOCB-13929). External deep links (/table_train_v3?token=…)
  // authenticate with a token from the URL and persist an org_id via
  // setUserSession(), but they never create an OAuth session — there is no
  // `token_details`. Firing this prefetch on such a page sends
  // feature_subscription/list + get_preferences + get_user_preferences with no
  // Authorization header; every one 401s, and ApiClient escalates a 401 into
  // refresh → redirectToLogin → logout(), which $resets the auth store and
  // wipes storage — destroying the URL-token session the page is running on.
  // Gate on the real session, the same check the tolgee boot file makes.
  const tokenDetails = LocalStorage.getItem('token_details');
  if (!tokenDetails || !tokenDetails.access_token) return;

  const org_id = userApiService.getOrgId();
  if (!org_id) return;

  // Fire-and-forget: the subscription check writes to Pinia stores that
  // components reactively read from. Awaiting here would block Vue mount
  // for the duration of the network call (feature_subscriptions + settings
  // fetch) without any synchronous consumer benefiting from the wait.
  subscriptionUtil.methods.checkSubscriptionValidity().catch((err) => {
    const error = typeof logError === 'function' ? logError : console.error;
    error('[SubscriptionAndConnectionChecker] Check failed:', err.message || err);
  });
});
